  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'A língua varia; a situação também importa', 'Português é heterogêneo e muda conforme tempo, lugar, grupos, gênero e situação. Aprender a variedade de referência formal amplia repertório; não torna outras variedades inferiores.', '## Uma língua, muitas variedades
A língua não é uma lista única e imóvel de frases. Há variações geográficas, históricas, sociais e situacionais; fala e escrita também oferecem recursos diferentes. Vocabulário, pronúncia, construções e formas de tratamento podem variar. Uma palavra diferente ou uma construção familiar a um grupo não prova, por si só, falta de lógica ou de capacidade. Para analisar um trecho, descreva o que aparece e em que contexto, sem imitar sotaques nem transformar pessoas em caricaturas.

## Registro, gênero e propósito
Uma conversa entre amigos, um requerimento, uma mensagem de serviço e uma apresentação oral têm objetivos e públicos diferentes. Falantes fazem escolhas de registro e estilo: vocabulário, grau de explicitação, tratamento, organização e convenções da escrita. A variedade de referência formal é importante em muitos gêneros institucionais e acadêmicos, e aprendê-la aumenta possibilidades de participação. Isso não significa que seja a única forma legítima de comunicar nem que uma fala cotidiana seja uma redação formal incompleta.

## Descrever não é hierarquizar
Uma análise descritiva pergunta quais padrões se repetem e que sentidos produzem. Uma regra de padronização define convenções para usos específicos, como a escrita formal. São perguntas relacionadas, mas não idênticas. Dizer que uma forma não segue uma convenção de determinado gênero pode ser preciso; dizer que o falante é menos inteligente por usar uma variedade é preconceito, não análise linguística. Na revisão, declare qual objetivo está em jogo: clareza, convenção solicitada, efeito de voz ou adequação ao público.

## Compare com responsabilidade
Para investigar variação, delimite uma pergunta, compare situações semelhantes e registre origem e contexto sem expor participantes. Uma amostra pequena mostra exemplos, não representa automaticamente toda uma cidade ou grupo. Em materiais históricos, a data, o gênero e a circulação ajudam a interpretar diferenças. Em comunicação pública, considere acessibilidade, linguagem simples e os repertórios do público. Preserve a voz quando ela é parte do gênero; adapte convenções quando o propósito pedir, explicando a escolha sem ridicularizar a forma de partida.

## Roteiro de leitura
1. Identifique gênero, público e propósito. 2. Descreva marcas observáveis sem rotular pessoas. 3. Considere tempo, lugar, grupo e modalidade apenas com evidências. 4. Avalie que efeito a escolha produz. 5. Se revisar, indique a convenção ou objetivo e mantenha respeito à identidade e à autoria.',
    'Uma associação envia um convite por áudio no grupo do bairro: “Sábado vai ter mutirão; quem puder chega às oito”. Depois, prepara um aviso impresso para o mural: “Mutirão comunitário no sábado, às 8h. A participação é aberta aos moradores”. Os textos cumprem propósitos próximos, mas organizam informação e tratamento de modo distinto para canais e públicos diferentes. O segundo explicita local e horário e usa convenções próprias do aviso; isso não torna o áudio inferior nem permite concluir como falam todos os moradores. A análise descreve escolhas e efeitos sem atribuir capacidade a um grupo.', array['Descreva a marca linguística antes de avaliá-la; não deduza identidade sem evidência.', 'Pergunte quem fala, para quem, por qual canal e com qual objetivo.', 'Ao revisar, nomeie a convenção específica e preserve a voz quando ela faz parte do gênero.', 'Não generalize um exemplo ou uma pequena amostra para uma região ou grupo inteiro.']::text[], 17, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-portuguese-language-variation","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Reconhecer interlocutor, finalidade e gênero em mensagens curtas.","Distinguir observação de julgamento sobre uma pessoa."],"key_concepts":["Variação pode ser geográfica, histórica, social, situacional ou relacionada à modalidade.","Registro e estilo são escolhas que respondem a gênero, público, canal e propósito.","A variedade de referência formal é um repertório útil para contextos específicos, não medida de inteligência ou valor humano.","Descrição de padrões linguísticos não é a mesma coisa que prescrição de convenções de um gênero.","Amostras precisam de contexto, consentimento e limites de generalização."],"progression":[{"stage":"FOUNDATION","focus":"Identificar diferenças de vocabulário e registro sem hierarquizar falantes.","questionIds":["v5-pt-variation-probe-01","v5-pt-variation-probe-02","v5-pt-variation-practice-01"]},{"stage":"APPLICATION","focus":"Relacionar escolhas a gênero, interlocutor, canal, tempo e propósito.","questionIds":["v5-pt-variation-practice-04","v5-pt-variation-practice-08","v5-pt-variation-practice-11"]},{"stage":"TRANSFER","focus":"Analisar amostras, comunicação pública e contextos novos com evidência e limites.","questionIds":["v5-pt-variation-transfer-01","v5-pt-variation-transfer-04","v5-pt-variation-transfer-07"]},{"stage":"INTEGRATION","focus":"Avaliar preconceito linguístico, escolhas editoriais e afirmações sobre grupos.","questionIds":["v5-pt-variation-lock-01","v5-pt-variation-lock-03","v5-pt-variation-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar descrição, adequação e respeito em gêneros diversos; o agendamento depende de mecanismo separado.","questionIds":["v5-pt-variation-review-01","v5-pt-variation-review-05","v5-pt-variation-review-09"]}],"micro_explanations":[{"trigger":"VARIATION_AS_ERROR","text":"Diferença é um dado a descrever. Para falar em inadequação, diga qual convenção do gênero ou objetivo não foi atendida."},{"trigger":"STANDARD_AS_ONLY_LANGUAGE","text":"A variedade formal é um repertório importante para certos contextos; ela não apaga os demais usos nem define valor humano."},{"trigger":"REGISTER_WITHOUT_CONTEXT","text":"Compare público, canal, gênero e propósito antes de avaliar uma escolha de linguagem."},{"trigger":"SAMPLE_AS_GROUP_RULE","text":"Uma amostra pequena oferece exemplos. Informe quem e o que foi observado antes de generalizar."}],"remediations":[{"misconception":"DIALECT_AS_DEFICIENCY","prompt":"Troque o rótulo sobre a pessoa por uma descrição observável da forma e pergunte que padrão ou contexto poderia explicá-la."},{"misconception":"ONE_REGISTER_FOR_ALL_GENRES","prompt":"Liste público, canal, gênero e propósito de duas mensagens; compare quais escolhas ajudam cada uma a cumprir sua função."},{"misconception":"STANDARD_EQUALS_LANGUAGE","prompt":"Separe em duas colunas: convenção da escrita formal e outros recursos linguísticos usados em situações cotidianas."},{"misconception":"PRESCRIPTION_AS_DESCRIPTION","prompt":"Reescreva a observação para distinguir um padrão encontrado na amostra de uma regra editorial exigida pelo gênero."},{"misconception":"SMALL_SAMPLE_GENERALIZATION","prompt":"Anote tamanho, origem, situação e limites da amostra; proponha que dados adicionais seriam necessários para uma afirmação mais ampla."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Base Nacional Comum Curricular: Ensino Médio, Linguagens e suas Tecnologias","publisher":"Ministério da Educação","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_20dez_site.pdf","accessedOn":"2026-10-13","supports":["language as variable and socially situated","respectful analysis of linguistic variation","choices suited to communicative situation"],"use":"Consulted as broad curriculum context only; no official mapping is claimed for this internal V3 skill code, and no wording or question was copied."},{"title":"Caderno educativo: Variação Linguística","publisher":"Museu da Língua Portuguesa, Acervo Digital","url":"https://acervo.museudalinguaportuguesa.org.br/publicacoes","accessedOn":"2026-10-13","supports":["regional vocabulary and ways of speaking","linguistic prejudice as a topic for reflection","educational treatment of Portuguese variation"],"use":"Reference for respectful instructional framing only; all scenarios and questions in this pack are original."},{"title":"Falares","publisher":"Museu da Língua Portuguesa, Acervo Digital","url":"https://acervo.museudalinguaportuguesa.org.br/exposicoes/1841/falares","accessedOn":"2026-10-13","supports":["geographic, sociocultural and temporal perspectives on Portuguese variation"],"use":"Used to check variation dimensions; no exhibit text or audio was reproduced."}],"copyright_note":"All example messages, scenarios, prompts, answer options, explanations and activities are original. Sources were consulted for conceptual accuracy and respectful framing only; no source wording, passage, recording or question was copied. This pack does not claim an official BNCC mapping or human pedagogical approval.","authentic_activities":[{"id":"v5-pt-variation-contextual-reading","title":"Duas mensagens, dois contextos","instructions":"Analise três mensagens fictícias criadas para a atividade: um áudio transcrito de convite entre colegas, um aviso de serviço e uma publicação curta em rede social. Sublinhe duas escolhas de vocabulário, tratamento ou organização em cada uma; identifique público, canal e propósito; depois adapte uma mensagem para outro gênero, anotando o que mudou e por quê. Não peça a colegas que imitem sotaques ou exponham expressões familiares.","evidence":"Quadro com marcas observadas, contexto e efeito provável; uma adaptação entre gêneros; justificativa que distingue convenção editorial de julgamento sobre falantes.","privacyGuard":"Os exemplos são fictícios e não devem ser substituídos por mensagens privadas, gravações ou nomes de pessoas. Não registrar sotaque, origem, raça, classe, endereço ou outra característica de colegas. A atividade pode ser feita individualmente com os textos fornecidos.","rubric":[{"criterion":"Descrição linguística","emerging":"Classifica uma forma como errada sem apontar evidência.","developing":"Identifica marcas, mas mistura descrição e avaliação normativa.","proficient":"Descreve marcas observáveis e as relaciona a contexto sem inferir identidade não informada."},{"criterion":"Gênero e adequação","emerging":"Propõe a mesma linguagem para qualquer público e propósito.","developing":"Reconhece o gênero, mas justifica escolhas de modo genérico.","proficient":"Adapta escolhas ao público, canal e objetivo, nomeando convenções pertinentes."},{"criterion":"Respeito e evidência","emerging":"Hierarquiza falantes ou generaliza a partir de um exemplo.","developing":"Evita insultos, mas não explicita os limites da amostra.","proficient":"Argumenta com exemplos, evita estigmas e declara limites da interpretação."}]}],"objective":"Analisar marcas de variação linguística e escolhas de registro considerando contexto, interlocutores, gênero e propósito, sem confundir diferença com deficiência.","common_mistake":"Tratar a variedade formal como a língua inteira, associar sotaque ou construção a inteligência, ou chamar qualquer diferença de erro sem considerar gênero e propósito.","estimated_minutes":17}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 5
     and metadata->>'content_id' = 'v5-portuguese-language-variation' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-pt-variation-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"CONVITE_AUDIO_E_CARTAZ","statement":"Uma pessoa convida colegas por áudio: “A gente se encontra às seis, beleza?”. No cartaz do evento, lê-se: “O encontro começa às 18h”. O que a comparação permite concluir?","options":["Os textos usam escolhas diferentes para canais e gêneros distintos, sem que isso prove inferioridade de quem produziu o áudio.","O áudio é defeituoso porque não usa a mesma construção do cartaz.","O cartaz mostra como todas as pessoas do grupo falam em qualquer situação.","Não é possível entender nenhum dos textos sem uniformizar a linguagem."],"correctAnswer":"Os textos usam escolhas diferentes para canais e gêneros distintos, sem que isso prove inferioridade de quem produziu o áudio.","explanation":"Áudio de convite e cartaz têm canais e convenções diferentes. A diferença pode ser analisada em relação ao propósito, não como medida de capacidade.","hint":"Observe quem recebe cada mensagem e como ela circula.","errorFocus":"REGISTER_WITHOUT_CONTEXT","misconceptions":{"O áudio é defeituoso porque não usa a mesma construção do cartaz.":["DIALECT_AS_DEFICIENCY"],"O cartaz mostra como todas as pessoas do grupo falam em qualquer situação.":["REGISTER_AS_FIXED_IDENTITY"],"Não é possível entender nenhum dos textos sem uniformizar a linguagem.":["VARIATION_BLOCKS_COMPREHENSION"]},"position":1},{"id":"v5-pt-variation-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"NOMES_DE_UM_TUBERCULO","statement":"Em materiais de diferentes localidades, o mesmo alimento aparece chamado de “mandioca”, “aipim” ou “macaxeira”. Qual leitura é mais adequada?","options":["Uma das palavras precisa ser erro de digitação.","A diferença lexical pode refletir usos regionais; é preciso observar contexto antes de generalizar.","A palavra mais longa é necessariamente mais formal.","O nome usado em um texto prova a origem de quem escreveu."],"correctAnswer":"A diferença lexical pode refletir usos regionais; é preciso observar contexto antes de generalizar.","explanation":"Variação lexical pode ocorrer entre lugares e comunidades. Uma ocorrência isolada não identifica com certeza a origem de uma pessoa nem estabelece uma hierarquia.","hint":"Diferencie uma possibilidade de uso de uma conclusão sobre cada falante.","errorFocus":"SAMPLE_AS_GROUP_RULE","misconceptions":{"Uma das palavras precisa ser erro de digitação.":["VARIATION_AS_ERROR"],"A palavra mais longa é necessariamente mais formal.":["FORMALITY_BY_WORD_LENGTH"],"O nome usado em um texto prova a origem de quem escreveu.":["IDENTITY_INFERRED_FROM_SINGLE_FEATURE"]},"position":2},{"id":"v5-pt-variation-probe-03","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"EVALUATE","contextFamily":"RELATORIO_DE_LABORATORIO","statement":"Um relatório escolar solicita linguagem formal e explicitação do procedimento. Qual justificativa para revisar o texto atende ao pedido sem desvalorizar a fala cotidiana do autor?","options":["A fala cotidiana é incapaz de expressar ideias complexas.","Toda mensagem deve usar a mesma forma, independentemente do público.","O relatório deve seguir convenções do gênero para que leitores compreendam método e resultados.","O autor deve apagar qualquer marca de identidade para parecer inteligente."],"correctAnswer":"O relatório deve seguir convenções do gênero para que leitores compreendam método e resultados.","explanation":"A revisão se justifica pelas convenções e pelo propósito do relatório. Isso não permite avaliar o valor ou a inteligência do autor pela variedade que usa em outras situações.","hint":"Aponte o objetivo comunicativo específico, não um julgamento sobre a pessoa.","errorFocus":"STANDARD_EQUALS_LANGUAGE","misconceptions":{"A fala cotidiana é incapaz de expressar ideias complexas.":["DIALECT_AS_DEFICIENCY"],"Toda mensagem deve usar a mesma forma, independentemente do público.":["ONE_REGISTER_FOR_ALL_GENRES"],"O autor deve apagar qualquer marca de identidade para parecer inteligente.":["STANDARD_AS_SOCIAL_SUPERIORITY"]},"position":3},{"id":"v5-pt-variation-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"TRATAMENTO_EM_CONSULTA","statement":"Em uma recepção, uma atendente pergunta “Você prefere aguardar aqui?”; ao falar com uma criança conhecida, diz “Quer esperar aqui?”. O que mais ajuda a explicar a mudança?","options":["A atendente esqueceu como se fala corretamente.","A primeira frase é sempre superior em qualquer conversa.","A segunda frase não pode cumprir uma finalidade comunicativa.","O tratamento e a formulação podem variar conforme interlocutor e situação."],"correctAnswer":"O tratamento e a formulação podem variar conforme interlocutor e situação.","explanation":"As escolhas podem responder à relação entre interlocutores e ao contexto. Não há evidência de que uma forma seja universalmente melhor.","hint":"Considere a relação social e a finalidade da pergunta.","errorFocus":"REGISTER_WITHOUT_CONTEXT","misconceptions":{"A atendente esqueceu como se fala corretamente.":["VARIATION_AS_ERROR"],"A primeira frase é sempre superior em qualquer conversa.":["ONE_REGISTER_FOR_ALL_GENRES"],"A segunda frase não pode cumprir uma finalidade comunicativa.":["COMMUNICATIVE_FUNCTION_DENIED"]},"position":1},{"id":"v5-pt-variation-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"EXPRESSAO_QUE_MUDA_COM_O_TEMPO","statement":"Uma carta fictícia de 1970 usa uma expressão que quase não aparece nas conversas atuais da turma. Qual hipótese é mais prudente?","options":["A expressão pode refletir usos de outra época; a data e o gênero ajudam a interpretá-la.","A carta está errada porque não usa palavras atuais.","A expressão prova que todos os jovens da época falavam da mesma maneira.","A mudança de vocabulário demonstra que a língua perdeu regras."],"correctAnswer":"A expressão pode refletir usos de outra época; a data e o gênero ajudam a interpretá-la.","explanation":"Usos podem mudar ao longo do tempo. Uma carta é uma amostra situada, não retrato completo de uma geração.","hint":"Relacione a forma à data e ao gênero, sem fazer uma generalização total.","errorFocus":"HISTORICAL_VARIATION_AS_DEFICIENCY","misconceptions":{"A carta está errada porque não usa palavras atuais.":["PRESENTISM_AS_CORRECTION"],"A expressão prova que todos os jovens da época falavam da mesma maneira.":["SAMPLE_AS_GROUP_RULE"],"A mudança de vocabulário demonstra que a língua perdeu regras.":["LANGUAGE_CHANGE_AS_DECAY"]},"position":2},{"id":"v5-pt-variation-practice-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"TEXTO_FALADO_E_TRANSCRICAO","statement":"Uma entrevista foi transcrita e depois editada para publicação. A versão final reorganiza pausas e elimina repetições, sem mudar a ideia. O que a edição altera principalmente?","options":["A identidade linguística de toda a comunidade entrevistada.","O canal e as convenções de apresentação do texto, que devem ser informados se forem relevantes.","A prova de que a fala original era incapaz de comunicar.","A certeza de que todas as repetições eram erros gramaticais."],"correctAnswer":"O canal e as convenções de apresentação do texto, que devem ser informados se forem relevantes.","explanation":"Uma transcrição editada não é registro neutro de cada detalhe da fala. A edição pode mudar a apresentação e precisa ser transparente conforme a finalidade.","hint":"Separe a fala registrada das escolhas editoriais posteriores.","errorFocus":"SPEECH_WRITING_EQUIVALENCE","misconceptions":{"A identidade linguística de toda a comunidade entrevistada.":["SAMPLE_AS_GROUP_RULE"],"A prova de que a fala original era incapaz de comunicar.":["ORALITY_AS_DEFICIENCY"],"A certeza de que todas as repetições eram erros gramaticais.":["EDITING_AS_ERROR_LABEL"]},"position":3},{"id":"v5-pt-variation-practice-04","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"RELATE","contextFamily":"MENSAGEM_DE_ALERTA_PUBLICO","statement":"Uma equipe precisa avisar moradores sobre interrupção de água. Qual planejamento considera melhor a situação comunicativa?","options":["Usar apenas termos técnicos para demonstrar autoridade.","Escrever como se fosse uma conversa privada entre integrantes da equipe.","Escolher linguagem clara, indicar horário e canal de dúvida e verificar se o público consegue agir com a informação.","Evitar explicar o motivo para que todas as pessoas leiam a mesma frase."],"correctAnswer":"Escolher linguagem clara, indicar horário e canal de dúvida e verificar se o público consegue agir com a informação.","explanation":"Aviso público deve facilitar compreensão e ação. Linguagem simples e explicitação podem ser adequadas sem desrespeitar a variedade linguística do público.","hint":"Pense no que o leitor precisa fazer depois de receber o aviso.","errorFocus":"AUDIENCE_PURPOSE_IGNORED","misconceptions":{"Usar apenas termos técnicos para demonstrar autoridade.":["TECHNICALITY_AS_CLARITY"],"Escrever como se fosse uma conversa privada entre integrantes da equipe.":["ONE_REGISTER_FOR_ALL_GENRES"],"Evitar explicar o motivo para que todas as pessoas leiam a mesma frase.":["ACCESSIBILITY_AS_UNIFORMITY"]},"position":4},{"id":"v5-pt-variation-practice-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"DUAS_FORMAS_DE_PEDIR","statement":"Em um diálogo fictício, uma pessoa diz “Me manda o endereço quando puder”; em uma solicitação protocolada, escreve “Solicito o envio do endereço”. O que se pode analisar com segurança?","options":["A segunda construção é adequada a qualquer relação, privada ou institucional.","A primeira frase prova falta de educação de quem a escreveu.","A solicitação protocolada é mais clara apenas por ter mais palavras.","As formas diferem em registro e formulação; o contexto indica qual atende melhor ao propósito."],"correctAnswer":"As formas diferem em registro e formulação; o contexto indica qual atende melhor ao propósito.","explanation":"As duas mensagens fazem um pedido. Relação entre interlocutores e gênero ajudam a explicar a escolha, sem deduzir caráter ou competência.","hint":"Compare o contexto de circulação, não o valor das pessoas.","errorFocus":"REGISTER_AS_PERSONALITY","misconceptions":{"A segunda construção é adequada a qualquer relação, privada ou institucional.":["ONE_REGISTER_FOR_ALL_GENRES"],"A primeira frase prova falta de educação de quem a escreveu.":["REGISTER_AS_PERSONALITY"],"A solicitação protocolada é mais clara apenas por ter mais palavras.":["LENGTH_AS_CLARITY"]},"position":5},{"id":"v5-pt-variation-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"EMOJI_EM_GRUPO_DE_TURMA","statement":"Em um grupo de colegas, alguém responde “chego já 🙂”. Em um formulário de inscrição, a mesma resposta não informa o horário esperado. Qual explicação é mais precisa?","options":["O efeito depende do gênero, do público e da precisão exigida; o formulário pode pedir horário explícito.","O emoji torna qualquer mensagem informal e inútil.","Mensagens digitais não têm convenções próprias.","A resposta prova que a pessoa não sabe escrever formalmente."],"correctAnswer":"O efeito depende do gênero, do público e da precisão exigida; o formulário pode pedir horário explícito.","explanation":"Recursos digitais participam da construção de sentido, mas um formulário pode exigir informação precisa que uma conversa contextualizada dispensa.","hint":"Compare o que o destinatário já sabe no grupo com o que precisa registrar no formulário.","errorFocus":"DIGITAL_GENRE_IGNORED","misconceptions":{"O emoji torna qualquer mensagem informal e inútil.":["DIGITAL_RESOURCE_AS_ERROR"],"Mensagens digitais não têm convenções próprias.":["MEDIUM_VARIATION_DENIED"],"A resposta prova que a pessoa não sabe escrever formalmente.":["ABILITY_INFERRED_FROM_ONE_MESSAGE"]},"position":6},{"id":"v5-pt-variation-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"REGRA_DE_EDITAL","statement":"Um edital pede que a resposta siga determinada convenção de escrita. Um aluno usa outra forma encontrada em sua fala cotidiana. Qual comentário do revisor é mais responsável?","options":["“Você fala errado e precisa mudar sua identidade linguística.”","“A forma não atende a convenção solicitada neste gênero; vamos revisá-la para o edital.”","“Toda diferença é preconceito, então não se pode revisar.”","“A fala cotidiana nunca comunica informações completas.”"],"correctAnswer":"“A forma não atende a convenção solicitada neste gênero; vamos revisá-la para o edital.”","explanation":"É possível ensinar e aplicar convenções de um gênero sem rotular o falante nem invalidar sua variedade cotidiana.","hint":"Nomeie a exigência textual e retire o julgamento sobre a pessoa.","errorFocus":"PRESCRIPTION_AS_PERSONAL_JUDGMENT","misconceptions":{"“Você fala errado e precisa mudar sua identidade linguística.”":["DIALECT_AS_DEFICIENCY"],"“Toda diferença é preconceito, então não se pode revisar.”":["CONVENTION_CANNOT_BE_TAUGHT"],"“A fala cotidiana nunca comunica informações completas.”":["ORALITY_AS_DEFICIENCY"]},"position":7},{"id":"v5-pt-variation-practice-08","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"COMENTARIO_SOBRE_SOTAQUE","statement":"Durante uma apresentação, um ouvinte diz que o sotaque de uma colega prova que ela não domina o conteúdo. Qual avaliação se apoia em evidências linguísticas?","options":["A afirmação é válida porque sotaques indicam conhecimento escolar.","A colega precisa esconder o sotaque antes de apresentar.","A afirmação confunde uma característica de pronúncia com domínio do conteúdo e não apresenta evidência sobre o argumento.","O sotaque define a variedade formal que ela pode aprender."],"correctAnswer":"A afirmação confunde uma característica de pronúncia com domínio do conteúdo e não apresenta evidência sobre o argumento.","explanation":"Uma característica de pronúncia, isoladamente, não demonstra conhecimento do tema. Avalie o conteúdo por suas ideias e evidências, sem estigmatizar o falante.","hint":"Pergunte se a característica citada mede realmente o conhecimento avaliado.","errorFocus":"ACCENT_AS_ABILITY","misconceptions":{"A afirmação é válida porque sotaques indicam conhecimento escolar.":["ACCENT_AS_ABILITY"],"A colega precisa esconder o sotaque antes de apresentar.":["ACCENT_ERASURE"],"O sotaque define a variedade formal que ela pode aprender.":["ABILITY_INFERRED_FROM_IDENTITY"]},"position":8},{"id":"v5-pt-variation-practice-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DESIGN","contextFamily":"PESQUISA_DE_VOCABULARIO","statement":"Uma turma quer descobrir quais nomes são usados para uma fruta em seu município. Qual plano evita generalização e exposição desnecessária?","options":["Perguntar a duas pessoas e declarar que toda a cidade usa a mesma palavra.","Gravar conversas privadas sem avisar para obter fala espontânea.","Corrigir as respostas antes de contar quais formas apareceram.","Reunir respostas voluntárias de perfis e locais variados, registrar o contexto sem nomes e relatar limites da amostra."],"correctAnswer":"Reunir respostas voluntárias de perfis e locais variados, registrar o contexto sem nomes e relatar limites da amostra.","explanation":"Amostragem diversa e consentimento melhoram a descrição; anonimização reduz exposição. Mesmo uma amostra maior tem limites que devem ser declarados.","hint":"Pense em consentimento, variedade de contextos e alcance da conclusão.","errorFocus":"SAMPLE_AND_PRIVACY","misconceptions":{"Perguntar a duas pessoas e declarar que toda a cidade usa a mesma palavra.":["SMALL_SAMPLE_GENERALIZATION"],"Gravar conversas privadas sem avisar para obter fala espontânea.":["CONSENT_IGNORED"],"Corrigir as respostas antes de contar quais formas apareceram.":["DATA_NORMALIZED_AWAY"]},"position":9},{"id":"v5-pt-variation-practice-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"LEGENDA_E_NARRACAO","statement":"Um vídeo tem narração formal e legenda curta com abreviações para caber na tela. Qual pergunta orienta uma análise melhor?","options":["Que escolhas de cada modalidade ajudam a informar nesse canal e limite de espaço?","Qual das duas pessoas fala o português correto?","Por que a legenda precisa copiar todas as pausas da fala?","Qual recurso prova que o público não entende linguagem formal?"],"correctAnswer":"Que escolhas de cada modalidade ajudam a informar nesse canal e limite de espaço?","explanation":"Narração e legenda trabalham com modalidades e restrições distintas. Compare função, espaço e público em vez de hierarquizar falantes.","hint":"Observe as condições de produção de cada parte do vídeo.","errorFocus":"MODALITY_HIERARCHY","misconceptions":{"Qual das duas pessoas fala o português correto?":["SPEECH_WRITING_HIERARCHY"],"Por que a legenda precisa copiar todas as pausas da fala?":["MODALITY_AS_COPY"],"Qual recurso prova que o público não entende linguagem formal?":["AUDIENCE_DEFICIT_ASSUMPTION"]},"position":10},{"id":"v5-pt-variation-practice-11","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"REVISE","contextFamily":"REVISAO_DE_RELATO_ORAL","statement":"Uma estudante escreve um relato oral de uma personagem fictícia para uma peça. A revisão quer melhorar a pontuação, mas preservar a voz da personagem. Qual procedimento é mais coerente?","options":["Substituir todas as expressões por linguagem burocrática.","Revisar legibilidade e convenções necessárias, mantendo escolhas que constroem a voz e o efeito pretendido.","Apagar qualquer traço de oralidade para provar domínio da escrita.","Manter erros de digitação porque qualquer revisão apaga identidade."],"correctAnswer":"Revisar legibilidade e convenções necessárias, mantendo escolhas que constroem a voz e o efeito pretendido.","explanation":"A revisão depende do gênero e da intenção estética. É possível corrigir aspectos que atrapalham a leitura sem apagar escolhas expressivas deliberadas.","hint":"Separe a forma que produz efeito de voz de problemas que impedem a leitura.","errorFocus":"VOICE_ERASURE_IN_EDITING","misconceptions":{"Substituir todas as expressões por linguagem burocrática.":["VOICE_ERASURE_IN_EDITING"],"Apagar qualquer traço de oralidade para provar domínio da escrita.":["ORALITY_AS_DEFICIENCY"],"Manter erros de digitação porque qualquer revisão apaga identidade.":["REVISION_AS_ERASURE"]},"position":11},{"id":"v5-pt-variation-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"DESIGN","contextFamily":"LEVANTAMENTO_DE_SAUDACOES","statement":"Uma equipe compara formas de saudação em mensagens voluntárias de três bairros. Qual conclusão pode ser sustentada por uma amostra pequena?","options":["A forma mais frequente é a única usada corretamente em todo o município.","Um bairro tem falantes mais educados porque usa uma saudação formal.","As formas observadas variaram na amostra; a equipe deve indicar tamanho, locais e limites antes de falar sobre o município.","A pesquisa prova que as diferenças são causadas apenas pela idade."],"correctAnswer":"As formas observadas variaram na amostra; a equipe deve indicar tamanho, locais e limites antes de falar sobre o município.","explanation":"A conclusão descreve os dados disponíveis e limita seu alcance. A amostra não autoriza inferências universais ou julgamento dos bairros.","hint":"Redija uma afirmação que não ultrapasse quem e o que foi observado.","errorFocus":"SAMPLE_AS_GROUP_RULE","misconceptions":{"A forma mais frequente é a única usada corretamente em todo o município.":["FREQUENCY_AS_CORRECTNESS"],"Um bairro tem falantes mais educados porque usa uma saudação formal.":["REGISTER_AS_INTELLIGENCE"],"A pesquisa prova que as diferenças são causadas apenas pela idade.":["SINGLE_CAUSE_FROM_SAMPLE"]},"position":1},{"id":"v5-pt-variation-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"ADAPT","contextFamily":"AVISO_PARA_PUBLICO_DIVERSO","statement":"Um centro de saúde prepara instruções para pessoas com diferentes níveis de familiaridade com termos médicos. Qual decisão melhora o acesso sem presumir incapacidade do público?","options":["Manter termos técnicos sem explicação para preservar autoridade.","Imitar formas de fala atribuídas a cada bairro.","Retirar todas as informações para que a mensagem fique curta.","Usar frases claras, explicar termos necessários e testar se as instruções permitem realizar a tarefa."],"correctAnswer":"Usar frases claras, explicar termos necessários e testar se as instruções permitem realizar a tarefa.","explanation":"Linguagem simples e teste de compreensão atendem ao propósito de serviço. Imitar grupos seria estereotipado; clareza não exige presumir falta de capacidade.","hint":"Avalie se o destinatário consegue agir com a informação.","errorFocus":"ACCESSIBILITY_AS_STIGMA","misconceptions":{"Manter termos técnicos sem explicação para preservar autoridade.":["JARGON_AS_AUTHORITY"],"Imitar formas de fala atribuídas a cada bairro.":["DIALECT_CARICATURE"],"Retirar todas as informações para que a mensagem fique curta.":["BREVITY_OVER_FUNCTION"]},"position":2},{"id":"v5-pt-variation-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"CARTA_ANTIGA_E_POSTAGEM_ATUAL","statement":"Uma pesquisadora compara uma carta de família de 1940 e publicações digitais atuais sobre o mesmo tema. O que deve ser considerado antes de atribuir diferenças apenas à época?","options":["Gênero, público, suporte, autoria e condições de produção também podem influenciar as formas observadas.","A data da carta basta para provar como todas as pessoas escreviam em 1940.","A publicação digital não pode ser analisada linguisticamente.","Toda diferença entre os textos prova que a língua perdeu qualidade."],"correctAnswer":"Gênero, público, suporte, autoria e condições de produção também podem influenciar as formas observadas.","explanation":"Tempo é uma dimensão, mas textos de gêneros e suportes distintos não formam comparação controlada. A análise precisa considerar outras condições.","hint":"Procure fatores além da data que diferem entre as duas fontes.","errorFocus":"TIME_AS_ONLY_CAUSE","misconceptions":{"A data da carta basta para provar como todas as pessoas escreviam em 1940.":["HISTORICAL_SAMPLE_GENERALIZATION"],"A publicação digital não pode ser analisada linguisticamente.":["DIGITAL_GENRE_IGNORED"],"Toda diferença entre os textos prova que a língua perdeu qualidade.":["LANGUAGE_CHANGE_AS_DECAY"]},"position":3},{"id":"v5-pt-variation-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"PRONOME_E_REFERENCIA","statement":"Em um diálogo fictício, a frase “Você pode trazer o documento quando voltar?” é respondida com “trago sim”. O que a resposta mostra sobre a leitura do diálogo?","options":["A frase é impossível porque não repete o pronome da pergunta.","A resposta pode ser interpretada pelo contexto compartilhado; a análise deve observar referência e sequência conversacional.","A forma prova a escolaridade de quem respondeu.","Toda resposta precisa repetir integralmente a estrutura da pergunta."],"correctAnswer":"A resposta pode ser interpretada pelo contexto compartilhado; a análise deve observar referência e sequência conversacional.","explanation":"Interlocutores usam contexto e elipses para construir sentido. Uma forma isolada não permite inferir escolaridade nem deve ser julgada fora da interação.","hint":"Leia pergunta e resposta juntas, como parte da mesma troca.","errorFocus":"CONTEXT_IGNORED_IN_INTERPRETATION","misconceptions":{"A frase é impossível porque não repete o pronome da pergunta.":["FORMAL_PATTERN_AS_ONLY_GRAMMAR"],"A forma prova a escolaridade de quem respondeu.":["ABILITY_INFERRED_FROM_ONE_FEATURE"],"Toda resposta precisa repetir integralmente a estrutura da pergunta.":["CONTEXTUAL_ELLIPSIS_DENIED"]},"position":4},{"id":"v5-pt-variation-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"ENTREVISTA_DE_MEMORIA_LOCAL","statement":"Um projeto registra memórias de moradores. Qual escolha respeita melhor participantes e qualidade da análise?","options":["Corrigir a fala durante a gravação sem informar para obter uma versão padronizada.","Publicar nomes e endereços para que a amostra pareça mais confiável.","Solicitar consentimento, explicar o uso, permitir recusa e registrar contexto sem expor dados desnecessários.","Pedir que cada participante imite um sotaque para facilitar a comparação."],"correctAnswer":"Solicitar consentimento, explicar o uso, permitir recusa e registrar contexto sem expor dados desnecessários.","explanation":"Consentimento e privacidade são requisitos éticos. Uma pesquisa deve documentar contexto e decisões de registro sem manipular participantes ou estigmatizar falares.","hint":"Avalie ética, transparência e o que realmente é necessário para responder à pergunta.","errorFocus":"CONSENT_AND_PRIVACY","misconceptions":{"Corrigir a fala durante a gravação sem informar para obter uma versão padronizada.":["DATA_NORMALIZED_AWAY"],"Publicar nomes e endereços para que a amostra pareça mais confiável.":["PRIVACY_IGNORED"],"Pedir que cada participante imite um sotaque para facilitar a comparação.":["DIALECT_CARICATURE"]},"position":5},{"id":"v5-pt-variation-transfer-06","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"ADAPT","contextFamily":"INSTRUCAO_EM_CANAL_DE_MENSAGEM","statement":"Uma biblioteca divulga a mesma oficina em um e-mail institucional e em uma mensagem curta para inscritos. Qual adaptação é coerente?","options":["Usar um texto idêntico mesmo que informações essenciais fiquem escondidas.","Retirar o horário da mensagem curta porque o público conhece o evento.","Usar gírias atribuídas ao público sem verificar se são compartilhadas.","Ajustar extensão e organização ao canal, mantendo data, local e ação necessária claros em ambos."],"correctAnswer":"Ajustar extensão e organização ao canal, mantendo data, local e ação necessária claros em ambos.","explanation":"A adaptação pode mudar organização e extensão, mas deve preservar a informação necessária para que cada público realize a ação.","hint":"Identifique o que pode mudar com o canal e o que não pode se perder.","errorFocus":"CHANNEL_ADAPTATION","misconceptions":{"Usar um texto idêntico mesmo que informações essenciais fiquem escondidas.":["ONE_REGISTER_FOR_ALL_GENRES"],"Retirar o horário da mensagem curta porque o público conhece o evento.":["ESSENTIAL_DETAIL_OMITTED"],"Usar gírias atribuídas ao público sem verificar se são compartilhadas.":["AUDIENCE_STEREOTYPING"]},"position":6},{"id":"v5-pt-variation-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"CRITIQUE","contextFamily":"PUBLICIDADE_SOTAQUE_COMO_PIADA","statement":"Uma campanha usa um sotaque regional como piada para representar falta de competência. Qual revisão melhora a peça sem proibir humor ou diversidade de vozes?","options":["Rever a associação entre sotaque e incompetência e avaliar se o humor pode funcionar sem estigmatizar um grupo.","Manter a associação, pois toda variedade regional pode ser usada como caricatura.","Retirar o sotaque de todas as personagens para evitar qualquer diferença.","Trocar o nome do lugar e conservar a mesma associação implícita."],"correctAnswer":"Rever a associação entre sotaque e incompetência e avaliar se o humor pode funcionar sem estigmatizar um grupo.","explanation":"A revisão considera o efeito social da representação. É possível manter humor e diversidade sem transformar uma variedade em sinal de incapacidade.","hint":"Identifique qual relação a campanha constrói entre uma forma de falar e uma qualidade pessoal.","errorFocus":"DIALECT_CARICATURE","misconceptions":{"Manter a associação, pois toda variedade regional pode ser usada como caricatura.":["STEREOTYPE_AS_HUMOR"],"Retirar o sotaque de todas as personagens para evitar qualquer diferença.":["VARIATION_ERASURE"],"Trocar o nome do lugar e conservar a mesma associação implícita.":["STIGMA_HIDDEN_NOT_REMOVED"]},"position":7},{"id":"v5-pt-variation-lock-01","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"CORRECAO_PUBLICA_DE_ALUNO","statement":"Durante uma aula, um estudante usa uma construção comum em sua comunidade ao explicar uma ideia. Qual intervenção ensina a convenção formal sem humilhá-lo?","options":["Dizer que a comunidade fala errado e pedir que a turma ria do exemplo.","Reconhecer a ideia, explicar qual convenção o gênero escolar solicita e praticar uma alternativa formal sem desqualificar a variedade usada.","Ignorar o conteúdo e avaliar somente a pronúncia.","Proibir o estudante de falar até abandonar sua variedade."],"correctAnswer":"Reconhecer a ideia, explicar qual convenção o gênero escolar solicita e praticar uma alternativa formal sem desqualificar a variedade usada.","explanation":"A escola pode ensinar repertórios formais explicitamente e, ao mesmo tempo, respeitar a variedade do estudante e avaliar o conteúdo por critérios pertinentes.","hint":"Separe o objetivo de aprendizagem do julgamento sobre a comunidade.","errorFocus":"TEACHING_STANDARD_WITHOUT_STIGMA","misconceptions":{"Dizer que a comunidade fala errado e pedir que a turma ria do exemplo.":["DIALECT_AS_DEFICIENCY"],"Ignorar o conteúdo e avaliar somente a pronúncia.":["ACCENT_AS_ABILITY"],"Proibir o estudante de falar até abandonar sua variedade.":["VARIATION_ERASURE"]},"position":1},{"id":"v5-pt-variation-lock-02","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"JUSTIFY","contextFamily":"EMAIL_DE_SOLICITACAO","statement":"Uma estudante escreve para solicitar uma bolsa e revisa o e-mail conforme as orientações do edital. Qual justificativa é adequada para a revisão?","options":["A variedade que ela usa em casa é inferior e precisa desaparecer.","E-mails formais não podem conter ideias pessoais.","O edital e o gênero estabelecem convenções que ajudam a tornar a solicitação clara e reconhecível.","A estudante só será compreendida se eliminar seu sotaque ao falar."],"correctAnswer":"O edital e o gênero estabelecem convenções que ajudam a tornar a solicitação clara e reconhecível.","explanation":"Convenções do gênero orientam a comunicação naquele contexto. Aprendê-las amplia repertório sem exigir o apagamento de outros usos.","hint":"Relacione a revisão ao propósito concreto da mensagem.","errorFocus":"STANDARD_AS_SOCIAL_SUPERIORITY","misconceptions":{"A variedade que ela usa em casa é inferior e precisa desaparecer.":["DIALECT_AS_DEFICIENCY"],"E-mails formais não podem conter ideias pessoais.":["GENRE_FEATURE_OVERGENERALIZATION"],"A estudante só será compreendida se eliminar seu sotaque ao falar.":["ACCENT_ERASURE"]},"position":2},{"id":"v5-pt-variation-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"TABELA_DE_FREQUENCIA_POR_BAIRRO","statement":"Uma tabela apresenta 12 respostas voluntárias de dois bairros e mostra três formas de nomear um objeto. Qual afirmação extrapola os dados?","options":["Na amostra, apareceram três formas diferentes.","As respostas vieram de dois bairros e de participantes voluntários.","Seria útil coletar mais dados em outras situações antes de generalizar.","A forma mais comum na tabela é a única correta em todo o município."],"correctAnswer":"A forma mais comum na tabela é a única correta em todo o município.","explanation":"Frequência numa amostra não transforma uma forma em única correta nem permite representar toda a cidade sem evidência adicional.","hint":"Compare o tamanho e a origem da amostra com o alcance da conclusão.","errorFocus":"FREQUENCY_AS_CORRECTNESS","misconceptions":{"Na amostra, apareceram três formas diferentes.":["OBSERVATION_MISREAD_AS_GENERALIZATION"],"As respostas vieram de dois bairros e de participantes voluntários.":["SAMPLE_CONTEXT_DENIED"],"Seria útil coletar mais dados em outras situações antes de generalizar.":["LIMITATION_AS_UNNECESSARY"]},"position":3},{"id":"v5-pt-variation-lock-04","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ADAPT","contextFamily":"FOLHETO_DE_SERVICO_MULTILINGUE","statement":"Um serviço público atende pessoas que usam português e outras línguas. Qual decisão combina clareza e respeito linguístico?","options":["Oferecer informação clara, recursos de acessibilidade e apoio linguístico quando necessário, sem ridicularizar repertórios.","Pedir que todos escondam qualquer outra língua para demonstrar integração.","Imitar a fala de cada grupo sem consulta para criar proximidade.","Retirar detalhes do serviço para evitar traduzir conceitos."],"correctAnswer":"Oferecer informação clara, recursos de acessibilidade e apoio linguístico quando necessário, sem ridicularizar repertórios.","explanation":"A comunicação pode reconhecer repertórios diversos e oferecer apoio para que a informação seja acessível, sem estereotipar pessoas.","hint":"Considere a tarefa que o público precisa realizar e os apoios que ampliam acesso.","errorFocus":"MULTILINGUAL_REPERTOIRE_STIGMA","misconceptions":{"Pedir que todos escondam qualquer outra língua para demonstrar integração.":["LANGUAGE_ERASURE"],"Imitar a fala de cada grupo sem consulta para criar proximidade.":["AUDIENCE_STEREOTYPING"],"Retirar detalhes do serviço para evitar traduzir conceitos.":["ACCESSIBILITY_AS_OMISSION"]},"position":4},{"id":"v5-pt-variation-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"DESCRICAO_E_REGRA_EDITORIAL","statement":"Uma gramática de uso descreve uma construção recorrente em conversas; um manual editorial recomenda outra forma para determinado documento. Como distinguir os enunciados?","options":["Ambos provam que uma comunidade é mais inteligente.","O primeiro pode descrever um padrão de uso; o segundo orienta uma convenção para um gênero ou instituição.","O manual editorial descreve necessariamente toda fala real.","A descrição de uso impede qualquer escolha formal na escrita."],"correctAnswer":"O primeiro pode descrever um padrão de uso; o segundo orienta uma convenção para um gênero ou instituição.","explanation":"Descrição de regularidades e recomendação editorial respondem a perguntas diferentes. Uma convenção pode orientar uma produção específica sem resumir todos os usos da língua.","hint":"Pergunte se cada texto relata um padrão observado ou recomenda uma escolha.","errorFocus":"PRESCRIPTION_AS_DESCRIPTION","misconceptions":{"Ambos provam que uma comunidade é mais inteligente.":["LANGUAGE_AS_INTELLIGENCE_SCALE"],"O manual editorial descreve necessariamente toda fala real.":["STANDARD_EQUALS_LANGUAGE"],"A descrição de uso impede qualquer escolha formal na escrita.":["DESCRIPTION_FORBIDS_REGISTER"]},"position":5},{"id":"v5-pt-variation-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"DUAS_PALAVRAS_PARA_MESMA_ACAO","statement":"Dois avisos fictícios usam palavras diferentes para a mesma ação, mas ambos indicam claramente onde e quando ela ocorrerá. O que pode ser afirmado?","options":["Um dos avisos é necessariamente incompreensível.","A palavra mais usada no grupo é a única correta.","Há escolhas lexicais diferentes e o sentido pode ser compreendido nos contextos apresentados.","A diferença prova que os autores pertencem a classes sociais distintas."],"correctAnswer":"Há escolhas lexicais diferentes e o sentido pode ser compreendido nos contextos apresentados.","explanation":"A evidência mostra diferença lexical e compreensão contextual. Não sustenta uma hierarquia ou inferência social automática.","hint":"Descreva o que os avisos realmente mostram.","errorFocus":"VARIATION_AS_ERROR","misconceptions":{"Um dos avisos é necessariamente incompreensível.":["VARIATION_BLOCKS_COMPREHENSION"],"A palavra mais usada no grupo é a única correta.":["FREQUENCY_AS_CORRECTNESS"],"A diferença prova que os autores pertencem a classes sociais distintas.":["IDENTITY_INFERRED_FROM_SINGLE_FEATURE"]},"position":1},{"id":"v5-pt-variation-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"ADAPT","contextFamily":"RECADO_DE_EQUIPE_PARA_CLIENTE","statement":"Uma equipe conversa em um grupo interno com abreviações. Para enviar a confirmação de horário a um cliente novo, qual passo é mais útil?","options":["Reproduzir as abreviações e presumir que o cliente conhece o contexto.","Concluir que abreviações provam falta de domínio da escrita.","Exigir que o grupo interno deixe de usar abreviações em qualquer situação.","Explicitar data, horário e ação em uma mensagem adequada ao canal e ao destinatário."],"correctAnswer":"Explicitar data, horário e ação em uma mensagem adequada ao canal e ao destinatário.","explanation":"A adaptação considera o que o novo destinatário sabe e precisa. O uso interno não permite julgar capacidade nem precisa ser proibido em todos os contextos.","hint":"Avalie o conhecimento compartilhado entre quem escreve e quem recebe.","errorFocus":"SHARED_CONTEXT_ASSUMPTION","misconceptions":{"Reproduzir as abreviações e presumir que o cliente conhece o contexto.":["AUDIENCE_CONTEXT_OVERASSUMED"],"Concluir que abreviações provam falta de domínio da escrita.":["ABILITY_INFERRED_FROM_ONE_MESSAGE"],"Exigir que o grupo interno deixe de usar abreviações em qualquer situação.":["ONE_REGISTER_FOR_ALL_GENRES"]},"position":2},{"id":"v5-pt-variation-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"FORMA_DE_PRONUNCIA_EM_AUDIO","statement":"Um áudio apresenta uma pronúncia diferente da usada pela locutora de um material didático. O que essa diferença permite concluir sozinha?","options":["Nada sobre competência ou origem com certeza; é preciso contexto e outras evidências.","Que a locutora do áudio não conhece a língua.","Que uma das pessoas precisa corrigir seu modo de falar.","Que o material didático representa todas as pronúncias possíveis."],"correctAnswer":"Nada sobre competência ou origem com certeza; é preciso contexto e outras evidências.","explanation":"Uma pronúncia isolada não basta para inferir competência nem origem. A comparação exige contexto e cautela contra estereótipos.","hint":"Pergunte quais conclusões a evidência realmente sustenta.","errorFocus":"ACCENT_AS_ABILITY","misconceptions":{"Que a locutora do áudio não conhece a língua.":["ACCENT_AS_ABILITY"],"Que uma das pessoas precisa corrigir seu modo de falar.":["ACCENT_ERASURE"],"Que o material didático representa todas as pronúncias possíveis.":["MODEL_AS_COMPLETE_VARIETY"]},"position":3},{"id":"v5-pt-variation-review-04","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"CRITIQUE","contextFamily":"TEXTO_HISTORICO_REVISADO","statement":"Uma exposição atualiza a ortografia de uma carta antiga e marca as alterações em nota. Por que essa transparência é importante?","options":["Porque prova que a grafia antiga estava errada em seu próprio tempo.","Porque permite distinguir a fonte histórica da intervenção editorial feita para leitores atuais.","Porque elimina qualquer necessidade de conhecer o contexto da carta.","Porque todas as fontes devem ser atualizadas sem aviso."],"correctAnswer":"Porque permite distinguir a fonte histórica da intervenção editorial feita para leitores atuais.","explanation":"A nota preserva a distinção entre documento e edição. A forma antiga deve ser interpretada em seu contexto, não julgada por convenções atuais sem explicação.","hint":"Separe o registro original das escolhas de quem prepara a exposição.","errorFocus":"EDITORIAL_CHANGE_UNDISCLOSED","misconceptions":{"Porque prova que a grafia antiga estava errada em seu próprio tempo.":["PRESENTISM_AS_CORRECTION"],"Porque elimina qualquer necessidade de conhecer o contexto da carta.":["CONTEXT_NOT_NEEDED"],"Porque todas as fontes devem ser atualizadas sem aviso.":["EDITORIAL_CHANGE_UNDISCLOSED"]},"position":4},{"id":"v5-pt-variation-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"FORMA_DE_TRATAMENTO_EM_ATENDIMENTO","statement":"Em dois atendimentos, profissionais usam formas de tratamento distintas, mas mantêm respeito e resolvem a solicitação. Qual leitura é sustentada?","options":["Só uma forma pode expressar respeito em qualquer região.","A forma menos comum prova descortesia.","A relação e a convenção local podem influenciar o tratamento; os exemplos não definem uma regra universal.","As duas formas têm necessariamente o mesmo efeito em todo contexto."],"correctAnswer":"A relação e a convenção local podem influenciar o tratamento; os exemplos não definem uma regra universal.","explanation":"Tratamento varia com relação, situação e convenções. Dois casos não bastam para afirmar que o efeito é universal ou hierárquico.","hint":"Use os contextos fornecidos e evite estender a conclusão a todos os lugares.","errorFocus":"TREATMENT_AS_UNIVERSAL","misconceptions":{"Só uma forma pode expressar respeito em qualquer região.":["ONE_FORM_AS_UNIVERSAL"],"A forma menos comum prova descortesia.":["FREQUENCY_AS_POLITENESS"],"As duas formas têm necessariamente o mesmo efeito em todo contexto.":["CONTEXT_EFFECT_DENIED"]},"position":5},{"id":"v5-pt-variation-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"REVISE","contextFamily":"LEGENDA_ACESSIVEL","statement":"Uma instituição revisa uma legenda automática para um vídeo. Qual critério é mais defensável?","options":["Preservar todo erro do reconhecimento automático para não editar a fala.","Substituir todas as escolhas da pessoa por um registro burocrático.","Retirar a legenda porque a fala já está disponível no vídeo.","Revisar nomes, pontuação e sentido para tornar a legenda fiel e legível, registrando limites quando necessário."],"correctAnswer":"Revisar nomes, pontuação e sentido para tornar a legenda fiel e legível, registrando limites quando necessário.","explanation":"Legenda acessível requer fidelidade e legibilidade. A revisão não precisa apagar a voz da pessoa nem manter falhas do sistema automático.","hint":"Considere simultaneamente acesso, fidelidade ao conteúdo e transparência editorial.","errorFocus":"ACCESSIBILITY_EDITING","misconceptions":{"Preservar todo erro do reconhecimento automático para não editar a fala.":["AUTOMATIC_TRANSCRIPT_AS_SOURCE"],"Substituir todas as escolhas da pessoa por um registro burocrático.":["VOICE_ERASURE_IN_EDITING"],"Retirar a legenda porque a fala já está disponível no vídeo.":["ACCESSIBILITY_IGNORED"]},"position":6},{"id":"v5-pt-variation-review-07","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"MENSAGEM_CURTA_DE_EMERGENCIA","statement":"Uma mensagem de emergência precisa ser entendida rapidamente por um público amplo. Qual revisão preserva melhor a função?","options":["Usar instruções diretas, informar local e horário e evitar ambiguidades relevantes.","Adicionar termos técnicos sem explicar para aumentar a formalidade.","Imitar uma variedade regional escolhida ao acaso.","Remover o verbo de ação para deixar a frase neutra."],"correctAnswer":"Usar instruções diretas, informar local e horário e evitar ambiguidades relevantes.","explanation":"A adequação é guiada pelo propósito urgente e pelas informações necessárias. Clareza pode ser planejada sem caricaturar variedades.","hint":"Descubra quais informações permitem que a pessoa aja com segurança.","errorFocus":"PURPOSE_IGNORED_IN_REVISION","misconceptions":{"Adicionar termos técnicos sem explicar para aumentar a formalidade.":["JARGON_AS_AUTHORITY"],"Imitar uma variedade regional escolhida ao acaso.":["DIALECT_CARICATURE"],"Remover o verbo de ação para deixar a frase neutra.":["ACTION_INFO_OMITTED"]},"position":7},{"id":"v5-pt-variation-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"REPERTORIO_BILIGUE","statement":"Uma estudante alterna português e outra língua ao conversar com familiares, mas usa português no relatório escolar. Qual interpretação é mais cuidadosa?","options":["Ela não domina nenhuma das línguas porque alterna repertórios.","A escolha pode responder a interlocutores, assunto e gênero; é preciso evidência antes de avaliar cada proficiência.","O relatório prova que a outra língua não tem regras.","Toda alternância deve ser eliminada em conversa e escrita."],"correctAnswer":"A escolha pode responder a interlocutores, assunto e gênero; é preciso evidência antes de avaliar cada proficiência.","explanation":"Falantes podem mobilizar repertórios conforme o contexto. Uma alternância ou um único texto não permite concluir o nível global de domínio.","hint":"Observe com quem e para que cada interação acontece.","errorFocus":"MULTILINGUAL_REPERTOIRE_STIGMA","misconceptions":{"Ela não domina nenhuma das línguas porque alterna repertórios.":["LANGUAGE_ALTERNATION_AS_DEFICIT"],"O relatório prova que a outra língua não tem regras.":["OTHER_LANGUAGE_AS_UNSTRUCTURED"],"Toda alternância deve ser eliminada em conversa e escrita.":["LANGUAGE_ERASURE"]},"position":8},{"id":"v5-pt-variation-review-09","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"ESCOLHA_DE_ESTILO_EM_REPORTAGEM","statement":"Uma reportagem inclui uma fala coloquial entre aspas e usa registro formal na narração. Qual análise melhor explica a diferença?","options":["A fala citada precisa ser reescrita para que a pessoa pareça competente.","A presença de fala coloquial torna toda a reportagem informal.","A narração e a citação têm funções distintas; a edição deve preservar fidelidade e contexto da fala.","A citação prova que todos os moradores usam a mesma construção."],"correctAnswer":"A narração e a citação têm funções distintas; a edição deve preservar fidelidade e contexto da fala.","explanation":"Voz narrativa e citação podem cumprir papéis diferentes. A edição responsável deixa claro o que foi dito e evita generalizar uma fala individual.","hint":"Separe a voz da reportagem da voz atribuída à pessoa citada.","errorFocus":"VOICE_AND_CITATION_CONFUSION","misconceptions":{"A fala citada precisa ser reescrita para que a pessoa pareça competente.":["DIALECT_AS_DEFICIENCY"],"A presença de fala coloquial torna toda a reportagem informal.":["GENRE_FEATURE_OVERGENERALIZATION"],"A citação prova que todos os moradores usam a mesma construção.":["SAMPLE_AS_GROUP_RULE"]},"position":9}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-portuguese-language-variation',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-portuguese-language-variation' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'PORTUGUESE', 'VARIACAO_LINGUISTICA', 'variedades registros e preconceito linguistico',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

